import XCTest
@testable import QAudionApp
import QAudionEngine

/// The voice word of the tone row against the shared acceptance table of `docs/voice-analysis-spec.md`,
/// section 12.6: after every step result the row says "voce", "silenzio" or nothing, by the same rule on both apps.
///
/// The table is `QAudionAppTests/voice-analysis/voice-word-cases.tsv`, a byte-for-byte copy of the file the Android
/// app runs too, generated by `docs/voice-analysis/gen_word_cases.py`. Each row is a sequence of steps (`V` a voiced
/// result, `u` an unvoiced one, `R` a reset or a gap of 2 s or more, which yields no result) and the word expected
/// after each result (`v` voice, `s` silence, `-` no word).
///
/// What it pins: a voiced result shows the voice word at once; a pause shorter than 20 results (2 s of audio) never
/// shows silence, whatever the voiced flag of the display value says; silence comes on the 20th unvoiced result in
/// a row; before any voice the row shows no word for 19 results; a reset forgets what was heard. Also pinned: the
/// word of each state exists, and no word is a state of its own; and the table reads the same with CRLF line
/// endings.
///
/// Wired into CI: on the include list of `QAudionApp/project-apptests.yml` and in the `-only-testing` list of
/// `.github/workflows/ios-app-tests.yml`.
final class VoiceWordTests: XCTestCase {

    // MARK: - The shared table

    private struct Case {
        let name: String
        let steps: String
        let expected: String
    }

    private static let columns = ["name", "steps", "expected", "description"]

    private func sourceURL(_ relativePath: String, file: StaticString = #filePath) throws -> URL {
        var dir = URL(fileURLWithPath: "\(file)")
        for _ in 0..<10 {
            dir = dir.deletingLastPathComponent()
            let candidate = dir.appendingPathComponent(relativePath)
            if FileManager.default.fileExists(atPath: candidate.path) { return candidate }
        }
        throw NSError(domain: "VoiceWordTests", code: 1,
                      userInfo: [NSLocalizedDescriptionKey: "\(relativePath) not found from \(file)"])
    }

    private func loadCases() throws -> [Case] {
        let url = try sourceURL("QAudionAppTests/voice-analysis/voice-word-cases.tsv")
        return try parseCases(try String(contentsOf: url, encoding: .utf8))
    }

    /// The cases of the text of the table. The lines end with LF or with CRLF (a checkout on Windows may convert the
    /// file), and `\r\n` is ONE Character in Swift: splitting on "\n" would not split a CRLF file at all, while
    /// `isNewline` is true for both.
    private func parseCases(_ text: String) throws -> [Case] {
        var rows: [[String]] = []
        for rawLine in text.split(whereSeparator: \.isNewline) {
            let line = String(rawLine)
            if line.isEmpty || line.hasPrefix("#") { continue }
            rows.append(line.components(separatedBy: "\t"))
        }
        let header = try XCTUnwrap(rows.first, "the table has no header")
        XCTAssertEqual(header, Self.columns, "the columns of the table changed")
        var cases: [Case] = []
        for row in rows.dropFirst() {
            XCTAssertEqual(row.count, Self.columns.count, "a row of the table: \(row.first ?? "")")
            guard row.count == Self.columns.count else { continue }
            cases.append(Case(name: row[0], steps: row[1], expected: row[2]))
        }
        return cases
    }

    /// The letter the table uses for a word.
    private func letter(_ word: VoiceWord) -> Character {
        switch word {
        case .voice: return "v"
        case .silence: return "s"
        case .noWord: return "-"
        }
    }

    /// The words after every result of `steps`, one letter per result.
    private func words(of steps: String, file: StaticString = #filePath, line: UInt = #line) -> String {
        var hold = VoiceWordHold()
        var out = ""
        for step in steps {
            switch step {
            case "V": out.append(letter(hold.update(voiced: true)))
            case "u": out.append(letter(hold.update(voiced: false)))
            case "R": hold.reset()
            default: XCTFail("unknown step \(step)", file: file, line: line)
            }
        }
        return out
    }

    func testEveryRowOfTheSharedTable() throws {
        let cases = try loadCases()
        XCTAssertGreaterThanOrEqual(cases.count, 10, "the table has its rows")
        for c in cases {
            let results = c.steps.filter { $0 == "V" || $0 == "u" }.count
            XCTAssertEqual(c.expected.count, results, "\(c.name): one word for each result of the steps")
            XCTAssertEqual(words(of: c.steps), c.expected, c.name)
        }
    }

    func testTheTableReadsTheSameWithCrlfLineEndings() throws {
        let url = try sourceURL("QAudionAppTests/voice-analysis/voice-word-cases.tsv")
        let text = try String(contentsOf: url, encoding: .utf8)
        let crlf = text.replacingOccurrences(of: "\r\n", with: "\n").replacingOccurrences(of: "\n", with: "\r\n")
        let plain = try parseCases(text)
        let converted = try parseCases(crlf)
        XCTAssertEqual(converted.count, plain.count)
        for (a, b) in zip(plain, converted) {
            XCTAssertEqual(a.name, b.name)
            XCTAssertEqual(a.steps, b.steps)
            XCTAssertEqual(a.expected, b.expected)
        }
    }

    // MARK: - The word of the row

    /// The row prints a word for a voice being heard and for silence, and none otherwise; the two words differ.
    func testTheRowPrintsAWordForVoiceAndForSilenceAndNoneOtherwise() throws {
        let voice = try XCTUnwrap(VoiceToneCopy.voiceWord(.voice))
        let silence = try XCTUnwrap(VoiceToneCopy.voiceWord(.silence))
        XCTAssertNotEqual(voice, silence)
        XCTAssertNil(VoiceToneCopy.voiceWord(.noWord))
    }

    /// Nothing is heard before the first voiced result, and nothing is said about it for the first 2 s.
    func testANewHoldShowsNoWord() {
        XCTAssertEqual(VoiceWordHold().word, .noWord)
    }
}
